package com.colheitagps.app

internal object ScreenHelp {
    fun text(title: String): String = when {
        title in setOf("Bem-vindo de volta","Criar conta","Concluir cadastro","Verificando acesso","Verificação de acesso") -> "Entre com sua matrícula e senha. O administrador também pode usar o e-mail cadastrado. No primeiro acesso, solicite uma conta, escolha sua frente, turno e perfil. Supervisores podem entrar ao concluir o cadastro; operadores aguardam aprovação do supervisor da mesma equipe. Se esqueceu a senha, use Recuperar senha."
        title.contains("administrador",true)||title.contains("acesso",true)||title.contains("Aprova",true) -> "Busque por nome ou matrícula e use os filtros para localizar pessoas. Abra um usuário para ver as ações. Supervisores aprovam operadores da própria frente e turno. Somente o administrador principal pode corrigir matrícula ou excluir a conta definitivamente."
        title.contains("Notifica",true) -> "Ative os avisos e autorize as notificações do Android. Supervisores recebem novidades da própria frente e turno; o administrador escolhe a frente que acompanha. Toque no aviso para abrir o registro após a sincronização. O teste verifica o recebimento neste celular."
        title.contains("Previsão",true) -> "Escolha o município de referência para consultar a previsão gratuita. A escolha não altera a equipe da conta. Confira o horário de atualização; com a internet indisponível, os dados anteriores podem continuar visíveis."
        title.contains("Atualizar",true) -> "Verifique a versão disponível, baixe a atualização e confirme a instalação no Android. Não desinstale nem limpe os dados. Se solicitado, autorize este aplicativo a instalar a atualização."
        title == "DM AGRO" -> "Escolha uma ferramenta para registrar ou consultar o trabalho da equipe. Em Configurações, organize suas favoritas e escolha o tema. Confira o indicador de sincronização antes de passar o turno."
        title == "Mapas" -> "Importe um PDF salvo no celular. O link da pasta do Google Drive ajuda a baixar mapas que faltam. Abra o mapa para pintar, medir, girar e acompanhar o GPS. Salve a pintura antes de compartilhar. Mapas pessoais permanecem privados."
        title.contains("Equipamento") || title.contains("Pendência", true) || title.matches(Regex("Histórico [0-9]+")) -> "Cadastre o equipamento e adicione as pendências. Marque urgência ou serviço para a parada de chuva quando necessário. Compartilhe uma pendência ou todas as abertas, por mensagem ou imagem, com ou sem foto. A manutenção preventiva fica nas opções do equipamento; somente o gestor programa revisões. Concluídos e excluídos permanecem no histórico."
        title.contains("Peça", true) -> "Informe código, descrição e quantidade. Você pode vincular a peça à pendência e acompanhar A pedir, Pedido ou Recebido. Receber a peça não conclui o serviço. Abra uma foto e toque em Marcar foto para indicar o defeito; a original fica preservada."
        title.contains("Estoque", true) -> "Cadastre um ou vários lotes. Área e produtividade aceitam texto livre; observações são opcionais. Escolha um lote existente para atualizar sem duplicar. No envio, escolha quais lotes levam foto ou mapa pintado da biblioteca. Enviar mensagem e fotos mantém os dados como mensagem; Enviar em PDF gera um documento separado. Confira a prévia e toque em Enviar."
        title.contains("Caminh", true) -> "Registre entrada e depois saída. A lista ativa acompanha o turno: A 07:00–15:20; B 15:20–23:20; C 23:20–07:00. A troca de turno esvazia a lista atual e preserva o histórico. Escolha uma data e um horário de corte para compartilhar o período desejado."
        title.contains("chuva", true) -> "Registre os milímetros, a data e a observação do turno. Consulte os registros da equipe e compartilhe por imagem. Para serviços a fazer quando chover, use o filtro de parada de chuva em Pendências."
        title.contains("Ocorrência", true) -> "Descreva o que aconteceu e o local, anexando fotos se desejar. O registro fica na equipe. O autor ou gestor pode editar; somente o gestor exclui ou restaura. Nas fotos, use Marcar foto para desenhar uma seta, um círculo ou uma observação."
        title.contains("Passagem de turno") -> "Escolha a data de início do turno da sua equipe. Pendências, peças e estoque mostram a situação atual; caminhões respeitam o período escolhido. Acrescente um recado, confira o conteúdo e compartilhe por mensagem ou imagem. Nenhum registro é encerrado ou apagado ao compartilhar."
        title.contains("Orde", true) || title.contains("O.S.") -> "Escolha o mapa para consultar suas ordens de serviço. O gestor pode editar ou encerrar uma O.S.; o encerramento mantém os dados no histórico."
        title.contains("Calendário", true) -> "Escolha uma data para consultar os registros do dia. Os dados permanecem separados por frente e turno."
        title == "Configurações" -> "Organize o início, confira a atualização e consulte a sincronização. Gestores também acessam notificações, registros excluídos e cópia de segurança. Atualize sem desinstalar ou limpar os dados."
        title.contains("excluído", true) -> "Itens excluídos ficam preservados. Somente o supervisor ou administrador pode restaurar os registros da equipe. Mapas pessoais mantêm a exceção de exclusão pelo próprio dono."
        else -> "Toque em um registro para ver as opções disponíveis para sua conta. O autor pode editar os próprios registros; gestores também podem excluir e restaurar. Fotos ficam no celular de quem anexou e podem ser compartilhadas. Use Voltar para retornar sem sair da conta."
    }
}
